import numpy as np
from scipy.optimize import fsolve

# Candidate A equation: R^3 + 3R^2 + 1 = 0
def poly_A(R):
    return R**3 + 3*R**2 + 1

# Initial guesses for real root searching
guesses = [-5, -4, -3]

roots_A = []
for g in guesses:
    try:
        root = fsolve(poly_A, g)[0]
        # Check if it's close to an actual root and is real
        if np.isreal(root):
            roots_A.append(root.real)
    except Exception:
        pass

print(f"Real roots found for R^3 + 3R^2 + 1 = 0: {sorted(list(set(roots_A))[:1]))}")

# Candidate B equation: R^3 + 3R^2 - 1 = 0
def poly_B(R):
    return R**3 + 3*R**2 - 1

# Initial guesses for real root searching
guesses_B = [-3, -2, -1]

roots_B = []
for g in guesses_B:
    try:
        root = fsolve(poly_B, g)[0]
        if np.isreal(root):
            roots_B.append(root.real)
    except Exception:
        pass

print(f"Real roots found for R^3 + 3R^2 - 1 = 0: {sorted(list(set(roots_B)))}")

